type AssetModule = string | { default: AssetModule }

const unwrap = (asset: AssetModule | undefined | null): string => {
    if (!asset) return ""
    if (typeof asset === "string") return asset
    return unwrap(asset.default)
}

const isResolvedUrl = (path: string) => (
    /^(?:\/|https?:|data:|blob:)/.test(path) || path.includes("static/")
)

const resolveInlinedAsset = (path: unknown, kind: "image" | "video") => {
    const value = unwrap(path as AssetModule)
    if (!value) return ""
    if (isResolvedUrl(value)) return value
    throw new Error(`${kind} asset was not inlined by the content loader: ${value}`)
}

export const resolveImage = (path: unknown) => resolveInlinedAsset(path, "image")
export const resolveVideo = (path: unknown) => resolveInlinedAsset(path, "video")
