import rawSiteConfig from "../content/site.yaml"

export type HeroActionLink = {
    label: string
    url: string
    unavailableMessage: string
}

export const VIDEO_BAR_STYLES = ["wash", "bar", "line"] as const
export type VideoBarStyle = (typeof VIDEO_BAR_STYLES)[number]

export const isVideoBarStyle = (value: unknown): value is VideoBarStyle => (
    typeof value === "string" && (VIDEO_BAR_STYLES as readonly string[]).includes(value)
)

export const VIDEO_CAPTION_STYLES = ["plain", "tag"] as const
export type VideoCaptionStyle = (typeof VIDEO_CAPTION_STYLES)[number]

export const isVideoCaptionStyle = (value: unknown): value is VideoCaptionStyle => (
    typeof value === "string" && (VIDEO_CAPTION_STYLES as readonly string[]).includes(value)
)

export const VIDEO_CAPTION_CORNERS = ["bottom-left", "bottom-right", "top-left", "top-right"] as const
export type VideoCaptionCorner = (typeof VIDEO_CAPTION_CORNERS)[number]

export const isVideoCaptionCorner = (value: unknown): value is VideoCaptionCorner => (
    typeof value === "string" && (VIDEO_CAPTION_CORNERS as readonly string[]).includes(value)
)

export const VIDEO_ACCENTS = ["red", "green"] as const
export type VideoAccent = (typeof VIDEO_ACCENTS)[number]

export const isVideoAccent = (value: unknown): value is VideoAccent => (
    typeof value === "string" && (VIDEO_ACCENTS as readonly string[]).includes(value)
)

export const VIDEO_MARKS = ["check", "x"] as const
export type VideoMark = (typeof VIDEO_MARKS)[number]

export const isVideoMark = (value: unknown): value is VideoMark => (
    typeof value === "string" && (VIDEO_MARKS as readonly string[]).includes(value)
)

export type SiteConfig = {
    site: {
        pageTitle: string
        siteUrl: string
        pathPrefix: string
        googleAnalyticsId: string
        favicon: string
    }
    features: {
        anonymous: boolean
        paperHero: boolean
        videoBarStyle?: VideoBarStyle
        videoCaptionStyle?: VideoCaptionStyle
        videoCaptionCorner?: VideoCaptionCorner
    }
    paperHero: {
        shortTitle: string
        titleHtml: string
        anonymousAuthorsLabel: string
        affiliationsLogo: string
        affiliationsLogoWidth?: number
        authors: Array<{
            name: string
            website?: string
            affiliations: string
            colorIndex?: number
            firstAuthor?: boolean
            correspondingAuthor?: boolean
        }>
        affiliations: Array<{ number: string; name: string; website?: string }>
        venue: { label: string; url: string }
        paper: HeroActionLink
        code: HeroActionLink
        tldr: string
    }
    citation: string
}

export const siteConfig = rawSiteConfig as SiteConfig

if (siteConfig.features.videoBarStyle && !isVideoBarStyle(siteConfig.features.videoBarStyle)) {
    throw new Error(`Unsupported video bar style: ${siteConfig.features.videoBarStyle}`)
}

if (siteConfig.features.videoCaptionStyle && !isVideoCaptionStyle(siteConfig.features.videoCaptionStyle)) {
    throw new Error(`Unsupported video caption style: ${siteConfig.features.videoCaptionStyle}`)
}

if (siteConfig.features.videoCaptionCorner && !isVideoCaptionCorner(siteConfig.features.videoCaptionCorner)) {
    throw new Error(`Unsupported video caption corner: ${siteConfig.features.videoCaptionCorner}`)
}

export const defaultVideoBarStyle = (): VideoBarStyle => (
    isVideoBarStyle(siteConfig.features.videoBarStyle) ? siteConfig.features.videoBarStyle : "wash"
)

export const defaultVideoCaptionStyle = (): VideoCaptionStyle => (
    isVideoCaptionStyle(siteConfig.features.videoCaptionStyle) ? siteConfig.features.videoCaptionStyle : "plain"
)

export const defaultVideoCaptionCorner = (): VideoCaptionCorner => (
    isVideoCaptionCorner(siteConfig.features.videoCaptionCorner) ? siteConfig.features.videoCaptionCorner : "bottom-left"
)
