import * as React from "react"

import mediaConfig from "../content/media.yaml"
import pageConfig from "../content/page.yaml"
import { resolveImage, resolveVideo } from "./content-assets"
import { isVideoAccent, isVideoBarStyle, isVideoCaptionCorner, isVideoCaptionStyle, isVideoMark, type VideoBarStyle, type VideoCaptionCorner, type VideoCaptionStyle } from "./content-config"
import {
    CitationBlock,
    FeaturedVideo,
    InteractiveDemo,
    MotivationComparison,
    ResultsTable,
    SectionHeading,
    VideoGrid,
    type ComparisonVideoItem,
    type ResultsTableProps,
    type VideoItem,
} from "./project-page"

type SectionStyle =
    | "abstract"
    | "demo"
    | "major-first"
    | "major"
    | "subsection"
    | "subsection-tight"
    | "minor"
    | "minor-tight"

type MarkdownStyle = "abstract" | "paragraph" | "list" | "list-section" | "list-spaced" | "default"

type MarkdownBlock = { type: "markdown"; source: string; style: MarkdownStyle; maxWidth?: string }
type VideoBlock = { type: "videos"; source: string; layout: "comparison" | "grid" | "featured"; barStyle?: VideoBarStyle; captionStyle?: VideoCaptionStyle; captionCorner?: VideoCaptionCorner }
type FigureBlock = { type: "figure"; image: string; alt: string; caption: string; description?: string }
type TableBlock = ResultsTableProps & { type: "table"; intro?: string }
type DemoBlock = { type: "demo" }
type CitationBlockConfig = { type: "citation" }
type PageBlock = MarkdownBlock | VideoBlock | FigureBlock | TableBlock | DemoBlock | CitationBlockConfig

export type PageSection = {
    id: string
    title: string
    navLabel?: string
    level: 2 | 3 | 4
    style: SectionStyle
    headingAlign?: "left" | "center" | "right"
    headingOffset?: string
    navIndent?: boolean
    visibility?: "public"
    enabled?: boolean
    blocks: PageBlock[]
}

export type SectionContent = Record<string, string>

type MediaConfigItem = VideoItem & {
    note?: string
    accent?: string
}

const configuredSections = (pageConfig as { sections: PageSection[] }).sections
const media = Object.fromEntries(
    Object.entries(mediaConfig as Record<string, MediaConfigItem[]>).map(([key, items]) => [
        key,
        items.map(item => {
            if (item.barStyle && !isVideoBarStyle(item.barStyle)) {
                throw new Error(`Unsupported video bar style in ${key}: ${item.barStyle}`)
            }
            if (item.captionStyle && !isVideoCaptionStyle(item.captionStyle)) {
                throw new Error(`Unsupported video caption style in ${key}: ${item.captionStyle}`)
            }
            if (item.captionCorner && !isVideoCaptionCorner(item.captionCorner)) {
                throw new Error(`Unsupported video caption corner in ${key}: ${item.captionCorner}`)
            }
            if (item.accent && !isVideoAccent(item.accent)) {
                throw new Error(`Unsupported video accent in ${key}: ${item.accent}`)
            }
            if (item.mark && !isVideoMark(item.mark)) {
                throw new Error(`Unsupported video mark in ${key}: ${item.mark}`)
            }
            return { ...item, video: resolveVideo(item.video) }
        }),
    ]),
) as Record<string, MediaConfigItem[]>

const headingClasses: Record<SectionStyle, string> = {
    abstract: "font-semibold text-center text-[var(--color-heading)] !mb-4",
    demo: "",
    "major-first": "font-semibold text-center text-[var(--color-heading)] !mb-3 text-lg",
    major: "font-semibold text-center text-[var(--color-heading)] !mb-3 !mt-20 text-lg",
    subsection: "text-[var(--color-heading)] text-base",
    "subsection-tight": "text-[var(--color-heading)] text-base",
    minor: "text-left text-[var(--color-heading)] !mt-36 !mb-2 text-base",
    "minor-tight": "text-left text-[var(--color-heading)] !mt-20 !mb-2 text-base",
}

const headingStyles: Partial<Record<SectionStyle, React.CSSProperties>> = {
    subsection: { marginTop: "4rem", marginBottom: "1.5rem" },
    "subsection-tight": { marginTop: "4rem", marginBottom: "0.1rem" },
}

const headingAlignClasses = {
    left: "text-left",
    center: "text-center",
    right: "text-right",
}

const markdownClasses: Record<MarkdownStyle, string> = {
    abstract: "markdown-abstract text-justify font-normal text-base sm:text-lg m-1 sm:m-1 max-w-[100%] sm:max-w-[800px]",
    paragraph: "markdown-paragraph mx-auto mt-3 max-w-[800px] text-left text-sm leading-relaxed text-[var(--color-body)] sm:text-base",
    list: "markdown-list",
    "list-section": "markdown-list",
    "list-spaced": "markdown-list markdown-list-spaced",
    default: "markdown-paragraph text-normal",
}

const markdownContainers: Partial<Record<MarkdownStyle, string>> = {
    abstract: "flex justify-center content-center",
    "list-section": "mx-auto mt-14 mb-12 max-w-[880px]",
}

const validatePageConfig = () => {
    const ids = new Set<string>()
    configuredSections.forEach(section => {
        if (ids.has(section.id)) throw new Error(`Duplicate page section id: ${section.id}`)
        if (!(section.style in headingClasses)) throw new Error(`Unsupported section style: ${section.style}`)
        if (section.headingAlign && !(section.headingAlign in headingAlignClasses)) {
            throw new Error(`Unsupported heading alignment: ${section.headingAlign}`)
        }
        if (section.headingOffset && (section.headingAlign !== "left" && section.headingAlign !== "right")) {
            throw new Error(`Heading offset requires left or right alignment: ${section.id}`)
        }
        section.blocks.forEach(block => {
            if (block.type === "markdown" && !(block.style in markdownClasses)) {
                throw new Error(`Unsupported Markdown style: ${block.style}`)
            }
            if (block.type === "videos" && block.barStyle && !isVideoBarStyle(block.barStyle)) {
                throw new Error(`Unsupported video bar style: ${block.barStyle}`)
            }
            if (block.type === "videos" && block.captionStyle && !isVideoCaptionStyle(block.captionStyle)) {
                throw new Error(`Unsupported video caption style: ${block.captionStyle}`)
            }
            if (block.type === "videos" && block.captionCorner && !isVideoCaptionCorner(block.captionCorner)) {
                throw new Error(`Unsupported video caption corner: ${block.captionCorner}`)
            }
        })
        ids.add(section.id)
    })
}

validatePageConfig()

export const getPageSections = (anonymized: boolean) => configuredSections.filter(section => (
    section.enabled !== false && (section.visibility !== "public" || !anonymized)
))

export const getRequiredMarkdownSources = (anonymized: boolean) => Array.from(new Set(
    getPageSections(anonymized).flatMap(section => section.blocks.flatMap(block => {
        if (block.type === "markdown") return [block.source]
        if (block.type === "figure" && block.description) return [block.description]
        if (block.type === "table" && block.intro) return [block.intro]
        return []
    })),
))

const MarkdownBody = ({ html, className = "", style }: { html: string; className?: string; style?: React.CSSProperties }) => (
    <div className={`markdown-content ${className}`} style={style} dangerouslySetInnerHTML={{ __html: html }} />
)

const getMarkdown = (sections: SectionContent, source: string) => {
    const html = sections[source]
    if (!html) throw new Error(`Missing Markdown content section: ${source}`)
    return html
}

const getMedia = (source: string) => {
    const items = media[source]
    if (!items) throw new Error(`Missing media collection: ${source}`)
    return items
}

const getComparisonItems = (source: string): ComparisonVideoItem[] => getMedia(source)

const MarkdownBlockView = ({ block, sections }: { block: MarkdownBlock; sections: SectionContent }) => (
    <div className={markdownContainers[block.style] ?? ""}>
        <MarkdownBody
            html={getMarkdown(sections, block.source)}
            className={markdownClasses[block.style]}
            style={block.maxWidth ? { maxWidth: block.maxWidth } : undefined}
        />
    </div>
)

const FigureBlockView = ({ block, sections }: { block: FigureBlock; sections: SectionContent }) => (
    <figure className="!my-6">
        <img src={resolveImage(block.image)} alt={block.alt} className="mx-auto w-full rounded-lg" />
        <figcaption className="mx-auto mt-3 max-w-[900px] text-center text-sm text-[var(--color-body)] sm:text-base">
            <b>{block.caption}</b>
        </figcaption>
        {block.description ? (
            <figcaption className="mx-auto mt-3 max-w-[960px] text-left text-sm leading-relaxed text-[var(--color-body)] sm:text-base">
                <MarkdownBody html={getMarkdown(sections, block.description)} className="markdown-method" />
            </figcaption>
        ) : null}
    </figure>
)

const VideoBlockView = ({ block }: { block: VideoBlock }) => {
    if (block.layout === "comparison") {
        return (
            <MotivationComparison
                items={getComparisonItems(block.source)}
                barStyle={block.barStyle}
                captionStyle={block.captionStyle}
                captionCorner={block.captionCorner}
            />
        )
    }
    if (block.layout === "featured") {
        const [item] = getMedia(block.source)
        if (!item) throw new Error(`Featured media collection is empty: ${block.source}`)
        return <FeaturedVideo {...item} barStyle={item.barStyle ?? block.barStyle} captionStyle={item.captionStyle ?? block.captionStyle} captionCorner={item.captionCorner ?? block.captionCorner} />
    }
    return <VideoGrid items={getMedia(block.source)} barStyle={block.barStyle} captionStyle={block.captionStyle} captionCorner={block.captionCorner} />
}

const TableBlockView = ({ block, sections }: { block: TableBlock; sections: SectionContent }) => (
    <div className="mx-auto mt-14 mb-12 max-w-[880px]">
        {block.intro ? (
            <MarkdownBody
                html={getMarkdown(sections, block.intro)}
                className="markdown-paragraph mx-auto max-w-[820px] text-left text-sm leading-relaxed text-[var(--color-body)] sm:text-base"
            />
        ) : null}
        <ResultsTable caption={block.caption} columns={block.columns} rows={block.rows} notes={block.notes} />
    </div>
)

const BlockView = ({ block, section, sections }: { block: PageBlock; section: PageSection; sections: SectionContent }) => {
    if (block.type === "markdown") return <MarkdownBlockView block={block} sections={sections} />
    if (block.type === "figure") return <FigureBlockView block={block} sections={sections} />
    if (block.type === "videos") return <VideoBlockView block={block} />
    if (block.type === "table") return <TableBlockView block={block} sections={sections} />
    if (block.type === "demo") return <InteractiveDemo id={section.id} title={section.title} label={section.navLabel ?? section.title} />
    if (block.type === "citation") return <CitationBlock />
    throw new Error(`Unsupported page block: ${(block as { type?: string }).type ?? "missing type"}`)
}

const SectionView = ({ section, sections }: { section: PageSection; sections: SectionContent }) => {
    const ownsHeading = section.blocks.some(block => block.type === "demo")
    const headingOffsetStyle = section.headingOffset
        ? section.headingAlign === "left"
            ? { marginLeft: section.headingOffset }
            : { marginRight: section.headingOffset }
        : undefined
    return (
        <>
            {!ownsHeading ? (
                <SectionHeading
                    id={section.id}
                    label={section.navLabel ?? section.title}
                    level={section.level}
                    className={`${headingClasses[section.style]} ${section.headingAlign ? headingAlignClasses[section.headingAlign] : ""}`}
                    style={{ ...headingStyles[section.style], ...headingOffsetStyle }}
                    divider={section.style === "major" || section.style === "major-first"}
                >
                    {section.title}
                </SectionHeading>
            ) : null}
            {section.blocks.map((block, index) => (
                <BlockView key={`${section.id}-${block.type}-${index}`} block={block} section={section} sections={sections} />
            ))}
        </>
    )
}

export const ProjectContent = ({ sections, anonymized }: { sections: SectionContent; anonymized: boolean }) => (
    <>
        {getPageSections(anonymized).map(section => (
            <SectionView key={section.id} section={section} sections={sections} />
        ))}
    </>
)
