import * as React from "react"
import { graphql, type HeadFC, type PageProps } from "gatsby"

import { resolveImage } from "../components/content-assets"
import { siteConfig } from "../components/content-config"
import {
    getPageSections,
    getRequiredMarkdownSources,
    ProjectContent,
    type SectionContent,
} from "../components/project-content"
import {
    Article,
    Main,
    ProjectFooter,
    ProjectHeader,
    TableOfContents,
    type TocItem,
    usePageVideos,
} from "../components/project-page"
import "../styles/color.css"

const ANONYMIZED = siteConfig.features.anonymous
const SHOW_PAPER_HERO = siteConfig.features.paperHero
const affiliationsLogo = resolveImage(siteConfig.paperHero.affiliationsLogo)

const EMPTY_FAVICON = "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg'/%3E"

type MarkdownSectionNode = {
    html: string | null
    frontmatter: { key: string | null } | null
}

type IndexPageData = {
    allMarkdownRemark: { nodes: MarkdownSectionNode[] }
}

const pageSections = getPageSections(ANONYMIZED)
const requiredSections = getRequiredMarkdownSources(ANONYMIZED)

const collectSections = (nodes: MarkdownSectionNode[]): SectionContent => {
    const sections = Object.fromEntries(
        nodes.flatMap(node => node.frontmatter?.key && node.html
            ? [[node.frontmatter.key, node.html]]
            : []),
    ) as SectionContent

    requiredSections.forEach(key => {
        if (!sections[key]) throw new Error(`Missing Markdown content section: ${key}`)
    })

    return sections
}

const tocItems: TocItem[] = pageSections.map(section => ({
    id: section.id,
    label: section.navLabel ?? section.title,
    indent: section.navIndent,
}))

export const Head: HeadFC = () => (
    <>
        <title>{siteConfig.site.pageTitle}</title>
        {ANONYMIZED ? (
            <>
                <link rel="icon" href={EMPTY_FAVICON} />
                <link rel="shortcut icon" href={EMPTY_FAVICON} />
                <link rel="apple-touch-icon" href={EMPTY_FAVICON} />
            </>
        ) : null}
    </>
)

const IndexPage: React.FC<PageProps<IndexPageData>> = ({ data }) => {
    usePageVideos()
    const sections = collectSections(data.allMarkdownRemark.nodes)

    return (
        <Main>
            <div className="relative">
                {/* TOC 侧边栏布局（整体位置在此调整）：
                    - hidden xl:block：仅在 xl 断点（≥1280px）显示
                    - absolute top-10 lg:top-12：相对主内容区的垂直起始偏移
                    - w-44：目录栏宽度
                    - left calc：水平位置，以 66rem 内容区居中为基准向左偏移；
                      增大末尾的 16rem 则目录更靠左，减小则更靠右
                    - 内层 sticky top-36：滚动时目录粘顶距离（需与 header 高度协调）
                    - TableOfContents 组件内的 sticky top-24（project-page.tsx）控制 nav 自身的粘顶偏移 */}
                <aside
                    className="hidden xl:block absolute top-10 lg:top-12 bottom-0 w-44"
                    style={{ left: "max(0.5rem, calc((100% - 66rem) / 2 - 14rem))" }}
                >
                    <div className="sticky top-36">
                        <TableOfContents items={tocItems} />
                    </div>
                </aside>

                {SHOW_PAPER_HERO ? (
                    <>
                        <div className="pt-10 lg:pt-12">
                            <Article>
                                <ProjectHeader anonymized={ANONYMIZED} affiliationsLogo={affiliationsLogo} />
                            </Article>
                        </div>
                        <br />
                        <br />
                    </>
                ) : null}

                <Article>
                    <ProjectContent sections={sections} anonymized={ANONYMIZED} />
                </Article>

                <ProjectFooter anonymized={ANONYMIZED} />
            </div>
        </Main>
    )
}

export const query = graphql`
    query IndexPage {
        allMarkdownRemark(
            filter: { fileAbsolutePath: { regex: "/src/content/sections/" } }
        ) {
            nodes {
                html
                frontmatter {
                    key
                }
            }
        }
    }
`

export default IndexPage
