export const HeadingAnchor = ({ id, label }: { id: string; label: string }) => (
    <a
        className="heading-anchor"
        href={`#${id}`}
        aria-label={`Link to ${label}`}
        title={`Link to ${label}`}
    >
        <FaLink aria-hidden="true" />
    </a>
)

export const SectionHeading = ({
    id,
    children,
    label,
    level = 2,
    className = "",
    style,
    divider = false,
}: HeadingProps) => {
    const Tag = `h${level}` as keyof JSX.IntrinsicElements
    return (
        <>
            <Tag id={id} className={className} style={style}>
                {children}
                <HeadingAnchor id={id} label={label ?? String(children)} />
            </Tag>
            {divider ? <div className="title-divider" /> : null}
        </>
    )
}

const Author = ({
    children,
    website,
    firstAuthor,
    affiliations,
    lastAuthor,
    corresAuthor,
    colorIndex = 0,
}: AuthorProps) => {
    const nameClass = `font-normal text-lg lg:text-xl ${AUTHOR_COLOR_CLASSES[colorIndex % AUTHOR_COLOR_CLASSES.length]}`
    return (
        <span className="text-center inline-block">
            {website ? (
                <a
                    href={website}
                    target="_blank"
                    rel="noreferrer"
                    className={`${nameClass} no-underline hover:underline underline-offset-3 hover:transition-all`}
                >
                    {children}
                </a>
            ) : (
                <span className={nameClass}>{children}</span>
            )}
            {firstAuthor || affiliations || corresAuthor ? (
                <sup className="pl-0.5">
                    {affiliations ?? null}
                    {firstAuthor ? <span>*</span> : null}
                    {corresAuthor ? <sup className="mr-0.5">&#8224;</sup> : null}
                </sup>
            ) : null}
            {lastAuthor ? null : <>,&nbsp;</>}
        </span>
    )
}

const Affiliation = ({ children, website, number }: React.PropsWithChildren<{ website?: string; number: string }>) => {
    const nameClass = "font-normal text-xs lg:text-sm text-stone-600"
    return (
        <span className="text-center inline-block mr-3">
            <sup className="mr-0.5">{number}</sup>
            {website ? (
                <a
                    href={website}
                    target="_blank"
                    rel="noreferrer"
                    className={`${nameClass} no-underline hover:underline underline-offset-3 hover:transition-all`}
                >
                    {children}
                </a>
            ) : (
                <span className={nameClass}>{children}</span>
            )}
        </span>
    )
}

const HERO_ACTION_BUTTON_CLASS =
    "no-underline font-normal text-sm text-[var(--color-action)] bg-[var(--action-button-bg)] border-2 border-[var(--color-action)] hover:bg-[var(--color-action)] hover:text-white hover:transition-all px-6 py-1 rounded-lg inline-flex items-center"

const HeroActionButton = ({
    label,
    url,
    unavailableMessage,
    icon,
}: HeroActionLink & { icon: React.ReactNode }) => {
    const buttonStyle = { "--action-button-bg": ACTION_BUTTON_BACKGROUND_COLOR } as React.CSSProperties

    if (url) {
        return (
            <span className="hero-action">
                <a
                    href={url}
                    target={url.startsWith("#") ? "_self" : "_blank"}
                    rel={url.startsWith("#") ? undefined : "noreferrer"}
                    className={HERO_ACTION_BUTTON_CLASS}
                    style={buttonStyle}
                >
                    {icon}
                    <span>{label}</span>
                </a>
            </span>
        )
    }

    return (
        <span className="hero-action">
            <button
                type="button"
                className={`${HERO_ACTION_BUTTON_CLASS} cursor-pointer`}
                style={buttonStyle}
                title={unavailableMessage}
            >
                {icon}
                <span>{label}</span>
            </button>
            {unavailableMessage ? <span className="hero-action-tip">{unavailableMessage}</span> : null}
        </span>
    )
}

