export const TableOfContents = ({ items }: { items: TocItem[] }) => {
    const [activeId, setActiveId] = React.useState("")

    React.useEffect(() => {
        const elements = items.map(({ id }) => document.getElementById(id)).filter(Boolean) as HTMLElement[]
        const observer = new IntersectionObserver(
            entries => {
                const active = entries.find(entry => entry.isIntersecting)
                if (active) setActiveId(active.target.id)
            },
            { rootMargin: "-10% 0px -80% 0px" },
        )
        elements.forEach(element => observer.observe(element))
        return () => observer.disconnect()
    }, [items])

    return (
        // sticky top-24：滚动粘顶偏移；整体左右位置见 index.tsx 的 <aside>
        <nav className="sticky top-24 text-sm leading-relaxed">
            <div className="font-semibold text-[var(--color-heading)] mb-2 uppercase tracking-wider">Contents</div>
            <ul className="border-l-2 border-gray-200">
                {items.map(item => (
                    <li key={item.id}>
                        <a
                            href={`#${item.id}`}
                            className={`block py-1.5 pl-3 border-l-2 -ml-0.5 transition-colors duration-150 ${activeId === item.id ? "border-[var(--color-action)] text-[var(--color-action)] font-medium" : "border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300"} ${item.indent ? "pl-7 text-xs" : "text-xs"}`}
                            onClick={event => {
                                event.preventDefault()
                                document.getElementById(item.id)?.scrollIntoView({ behavior: "smooth" })
                            }}
                        >
                            {item.label}
                        </a>
                    </li>
                ))}
            </ul>
        </nav>
    )
}

