export const CitationBlock = () => {
    const [copied, setCopied] = React.useState(false)
    const citation = siteConfig.citation
    const copyCitation = async () => {
        await navigator.clipboard.writeText(citation)
        setCopied(true)
        window.setTimeout(() => setCopied(false), 1600)
    }
    return (
        <div className="relative overflow-auto">
            <button
                type="button"
                onClick={copyCitation}
                aria-label={copied ? "Citation copied" : "Copy citation"}
                title={copied ? "Copied" : "Copy BibTeX"}
                className="absolute right-3 top-3 inline-flex h-8 w-8 items-center justify-center rounded-md border border-[var(--color-action)] bg-white/10 text-[var(--color-action-strong)] shadow-sm hover:bg-[var(--color-action)] hover:text-white hover:transition-all"
            >
                {copied ? <FiCheck aria-hidden="true" /> : <FiClipboard aria-hidden="true" />}
            </button>
            <pre className="bg-gradient-to-r from-orange-100/100 to-indigo-100 !my-0 pr-24">
                <code id="citation-bib" className="font-medium text-[var(--color-action-strong)] text-sm">{citation}</code>
            </pre>
        </div>
    )
}

