export const usePageVideos = () => {
    React.useEffect(() => {
        const handlers = new Map<HTMLVideoElement, EventListener>()
        const lockMute = (video: HTMLVideoElement) => {
            video.defaultMuted = true
            video.muted = true
            video.volume = 0
        }
        const register = (video: HTMLVideoElement) => {
            lockMute(video)
            if (handlers.has(video)) return
            const enforceMute: EventListener = () => lockMute(video)
            video.addEventListener("volumechange", enforceMute)
            video.addEventListener("play", enforceMute)
            video.addEventListener("loadedmetadata", enforceMute)
            handlers.set(video, enforceMute)
        }
        const registerAll = () => document.querySelectorAll("video").forEach(video => register(video))
        registerAll()
        const mutationObserver = new MutationObserver(registerAll)
        mutationObserver.observe(document.body, { childList: true, subtree: true })
        return () => {
            mutationObserver.disconnect()
            handlers.forEach((handler, video) => {
                video.removeEventListener("volumechange", handler)
                video.removeEventListener("play", handler)
                video.removeEventListener("loadedmetadata", handler)
            })
        }
    }, [])
}
